const { execFileSync } = require('child_process');
/** 7403 이 간헐적으로 뜬다 — 짧게 재시도한다. */
function d1(sql, tries = 4) {
  let last;
  for (let i = 0; i < tries; i += 1) {
    try {
      const out = execFileSync('node', ['D:/newmso/node_modules/wrangler/bin/wrangler.js','d1','execute','pchos-d1-v2','--remote','--json','--command',sql], { encoding:'utf8', maxBuffer:64*1024*1024 });
      const s = out.lastIndexOf('\n[\n');
      return JSON.parse(s>=0 ? out.slice(s+1) : out.slice(out.indexOf('[')))[0].results;
    } catch (e) {
      last = e;
      const txt = String(e.stdout || '');
      if (!txt.includes('7403')) throw e;
      execFileSync(process.execPath, ['-e', 'setTimeout(()=>{},1500)']);
    }
  }
  throw last;
}
module.exports = { d1 };

const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');
/** 긴 SQL 은 --command 로 못 넘긴다(윈도우 인자 길이). 파일로 넘긴다. */
function d1f(sql, tries = 4) {
  const tmp = path.join(__dirname, `q-${process.pid}-${sql.length}.sql`);
  fs.writeFileSync(tmp, sql, 'utf8');
  let last;
  try {
    for (let i = 0; i < tries; i += 1) {
      try {
        const out = execFileSync('node', ['D:/newmso/node_modules/wrangler/bin/wrangler.js','d1','execute','pchos-d1-v2','--remote','--json','--file',tmp], { encoding:'utf8', maxBuffer:128*1024*1024 });
        const s = out.lastIndexOf('\n[\n');
        const parsed = JSON.parse(s>=0 ? out.slice(s+1) : out.slice(out.indexOf('[')));
        return parsed.flatMap((p) => p.results || []);
      } catch (e) {
        last = e;
        if (!String(e.stdout || '').includes('7403')) throw e;
        execFileSync(process.execPath, ['-e', 'setTimeout(()=>{},1500)']);
      }
    }
    throw last;
  } finally {
    try { fs.unlinkSync(tmp); } catch {}
  }
}
module.exports = { d1f };

