// register-staff 의 permissions 루프를 옛 버전 / 새 버전으로 각각 재현해 비교한다.
const fs = require('fs');
const ADMIN_ONLY = new Set(['admin', 'mso', 'hr']);
const isPriv = (k) => k === 'system_master' || ADMIN_ONLY.has(k);

function oldCheck(perms, { actorIsAdmin, actorIsSystemMaster, actorPerms }) {
  for (const [key, value] of Object.entries(perms ?? {})) {
    if (value !== true) continue;
    if (key === 'system_master') { if (!actorIsSystemMaster) return `system_master 거부`; continue; }
    if (ADMIN_ONLY.has(key)) { if (!actorIsAdmin) return `${key} 거부`; continue; }
    if (!actorIsAdmin && actorPerms[key] !== true) return `없는권한 ${key} 거부`;
  }
  return null;
}

function newCheck(perms, { actorIsAdmin, actorIsSystemMaster, actorPerms }) {
  for (const [key, value] of Object.entries(perms ?? {})) {
    if (isPriv(key)) {
      if (!value) continue;
      if (key === 'system_master') { if (!actorIsSystemMaster) return `system_master 거부`; continue; }
      if (!actorIsAdmin) return `${key} 거부`;
      continue;
    }
    if (value !== true) continue;
    if (!actorIsAdmin && actorPerms[key] !== true) return `없는권한 ${key} 거부`;
  }
  return null;
}

