const { d1 } = require('./d1.cjs');
const pairs = JSON.parse(require('fs').readFileSync(__dirname + '/onconflict.json', 'utf8'));
const norm = (s) => s.split(',').map((x) => x.trim().toLowerCase()).sort().join(',');

// 테이블별 UNIQUE 인덱스 + PK 수집
const cache = {};
function uniqueSets(table) {
  if (cache[table]) return cache[table];
  const sets = [];
  try {
    const idx = d1(`PRAGMA index_list(${table})`);
    for (const i of idx) {
      if (Number(i.unique) !== 1) continue;
      const cols = d1(`PRAGMA index_info(${i.name})`).map((c) => c.name);
      sets.push({ name: i.name, cols: norm(cols.join(',')) });
    }
    const info = d1(`PRAGMA table_info(${table})`);
    const pk = info.filter((c) => Number(c.pk) > 0).sort((a, b) => a.pk - b.pk).map((c) => c.name);
    if (pk.length) sets.push({ name: '(PRIMARY KEY)', cols: norm(pk.join(',')) });
  } catch (e) {
    cache[table] = null;
    return null;
  }
  cache[table] = sets;
  return sets;
}

